  const ui=Oye(chapter);ui.el.dataset.kotoPreload=chapter;
  const cancel=document.createElement('button');cancel.textContent='取消加载 · 返回章节选择';cancel.dataset.kotoCancelLoad='true';
  cancel.style.cssText='padding:12px 28px;cursor:pointer';cancel.onclick=()=>document.dispatchEvent(new Event('koto-cancel-scene-load'));ui.el.append(cancel);
